const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY={products:"axoryn.products.v2",cart:"axoryn.cart.v2",favorites:"axoryn.favorites.v2",viewed:"axoryn.viewed.v2",orders:"axoryn.orders.v2",profile:"axoryn.profile.v2"};
const load=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let products=load(KEY.products,null) || structuredClone(SEED_PRODUCTS);
const state={cart:load(KEY.cart,[]),favorites:load(KEY.favorites,[]),viewed:load(KEY.viewed,[]),orders:load(KEY.orders,[]),profile:load(KEY.profile,{}),filters:{query:"",category:"Todos",brand:"Todos",max:500000,stock:false,offers:false,sort:"featured"}};
let editingProductId=null,pendingImageData=null,promoProductId=null;
const money=n=>new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(Number(n)||0);
const dateCL=v=>v?new Intl.DateTimeFormat("es-CL",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(v.includes("T")?v:v+"T12:00:00")):"";
const norm=v=>(v||"").toString().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const escapeHtml=v=>(v||"").toString().replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
function saveAll(){localStorage.setItem(KEY.products,JSON.stringify(products));localStorage.setItem(KEY.cart,JSON.stringify(state.cart));localStorage.setItem(KEY.favorites,JSON.stringify(state.favorites));localStorage.setItem(KEY.viewed,JSON.stringify(state.viewed));localStorage.setItem(KEY.orders,JSON.stringify(state.orders));localStorage.setItem(KEY.profile,JSON.stringify(state.profile));}
function toast(msg){const d=document.createElement("div");d.className="toast";d.textContent=msg;$("#toastRegion").appendChild(d);setTimeout(()=>d.remove(),2700)}
function isOffer(p){if(!p.offerPrice||Number(p.offerPrice)>=Number(p.price))return false;if(!p.offerUntil)return true;return new Date(p.offerUntil+"T23:59:59")>=new Date()}
function priceOf(p){return isOffer(p)?Number(p.offerPrice):Number(p.price)}
function discountPct(p){return isOffer(p)?Math.round((1-Number(p.offerPrice)/Number(p.price))*100):0}
function activeProducts(){return products.filter(p=>p.active!==false)}
function fallbackImage(){return "assets/products/tools.svg"}
function imgTag(p,cls=""){return `<img class="${cls}" src="${escapeHtml(p.image||fallbackImage())}" alt="${escapeHtml(p.name)}" onerror="this.onerror=null;this.src='${fallbackImage()}'">`}
function productCard(p){const fav=state.favorites.includes(p.id),offer=isOffer(p),stock=Number(p.stock)||0;return `<article class="product-card" data-id="${p.id}"><div class="product-image-wrap">${imgTag(p)}<div class="badges">${offer?`<span class="badge sale">-${discountPct(p)}%</span>`:""}${stock>0&&stock<=6?'<span class="badge low">Últimas unidades</span>':""}${stock<=0?'<span class="badge">Agotado</span>':""}</div><button class="fav-btn ${fav?"active":""}" data-action="fav" data-id="${p.id}" aria-label="Favorito"><svg><use href="#i-heart"></use></svg></button></div><div class="product-body"><div class="product-meta"><span>${escapeHtml(p.brand)}</span><span>${escapeHtml(p.sku)}</span></div><h3>${escapeHtml(p.name)}</h3><div class="compat">${escapeHtml(p.compatibility)}</div><div class="stock-line ${stock<=0?"out":stock<=6?"low":""}">${stock<=0?"Sin stock":stock<=6?`Sólo ${stock} disponibles`:`Stock disponible: ${stock}`}</div><div class="price-line"><b>${money(priceOf(p))}</b>${offer?`<span class="old-price">${money(p.price)}</span>`:""}</div>${offer&&p.offerUntil?`<div class="offer-until">Oferta hasta ${dateCL(p.offerUntil)}</div>`:""}<div class="card-actions"><button class="btn accent" data-action="add" data-id="${p.id}" ${stock<=0?"disabled":""}>Agregar al carrito</button><button class="icon-btn" data-action="view" data-id="${p.id}" aria-label="Ver detalle"><svg><use href="#i-arrow"></use></svg></button></div></div></article>`}
function renderCategoryNav(){const cats=["Todos",...new Set(activeProducts().map(p=>p.category).sort())];$("#categoryNav").innerHTML=cats.map(c=>`<button data-category="${escapeHtml(c)}" class="${state.filters.category===c?"active":""}">${escapeHtml(c)}</button>`).join("");const fc=$("#filterCategory");fc.innerHTML=cats.map(c=>`<option ${state.filters.category===c?"selected":""}>${escapeHtml(c)}</option>`).join("");const brands=["Todos",...new Set(activeProducts().map(p=>p.brand).sort())];$("#filterBrand").innerHTML=brands.map(b=>`<option ${state.filters.brand===b?"selected":""}>${escapeHtml(b)}</option>`).join("")}
function renderCategoryCards(){const cats=[...new Set(activeProducts().map(p=>p.category))].slice(0,8);$("#categoryCards").innerHTML=cats.map(c=>{const n=activeProducts().filter(p=>p.category===c).length;return `<button class="category-card" data-cat-card="${escapeHtml(c)}"><span>${n} producto${n===1?"":"s"}</span><b>${escapeHtml(c)}</b><span>Explorar categoría →</span></button>`}).join("")}
function renderFeatured(){const list=activeProducts().filter(p=>p.featured).slice(0,4);$("#featuredGrid").innerHTML=list.map(productCard).join("")}
function renderOffers(){const list=activeProducts().filter(isOffer).sort((a,b)=>discountPct(b)-discountPct(a));$("#offersSection").classList.toggle("hidden",!list.length);$("#offersGrid").innerHTML=list.slice(0,8).map(productCard).join("");$("#offerCountdown").textContent=list.length?`${list.length} ofertas vigentes`:"";const best=list[0];if(best){promoProductId=best.id;$("#promoTitle").textContent=best.name;$("#promoText").textContent=`Precio especial ${money(priceOf(best))}. Stock disponible: ${best.stock} unidades.`;$("#promoDiscount").textContent=`${discountPct(best)}%`;const banner=$("#promoBanner");banner.style.setProperty("--promo-image",`url("${best.image}")`)}}
function renderHero(){const ps=activeProducts();$("#heroStock").textContent=ps.reduce((a,p)=>a+(Number(p.stock)||0),0);$("#heroOffers").textContent=ps.filter(isOffer).length;$("#heroBrands").textContent=new Set(ps.map(p=>p.brand)).size}
function filteredProducts(){const f=state.filters;let list=activeProducts();if(f.query){const q=norm(f.query);list=list.filter(p=>norm([p.name,p.sku,p.brand,p.category,p.compatibility,p.description].join(" ")).includes(q))}if(f.category!=="Todos")list=list.filter(p=>p.category===f.category);if(f.brand!=="Todos")list=list.filter(p=>p.brand===f.brand);list=list.filter(p=>priceOf(p)<=f.max);if(f.stock)list=list.filter(p=>p.stock>0);if(f.offers)list=list.filter(isOffer);const sorters={"price-asc":(a,b)=>priceOf(a)-priceOf(b),"price-desc":(a,b)=>priceOf(b)-priceOf(a),name:(a,b)=>a.name.localeCompare(b.name,"es"),stock:(a,b)=>b.stock-a.stock,discount:(a,b)=>discountPct(b)-discountPct(a),featured:(a,b)=>Number(b.featured)-Number(a.featured)||a.id-b.id};return list.slice().sort(sorters[f.sort]||sorters.featured)}
function renderCatalog(){const list=filteredProducts();$("#productGrid").innerHTML=list.map(productCard).join("");$("#resultCount").textContent=`${list.length} producto${list.length===1?"":"s"}`;$("#emptyCatalog").classList.toggle("hidden",list.length>0)}
function renderHistory(){const list=state.viewed.map(id=>products.find(p=>p.id===id&&p.active!==false)).filter(Boolean).slice(0,5);$("#historySection").classList.toggle("hidden",!list.length);$("#historyGrid").innerHTML=list.map(productCard).join("")}
function renderAll(){renderCategoryNav();renderCategoryCards();renderFeatured();renderOffers();renderHero();renderCatalog();renderHistory();updateCounts();renderCart();renderManagement()}
function resetFilters(){state.filters={query:"",category:"Todos",brand:"Todos",max:500000,stock:false,offers:false,sort:"featured"};$("#globalSearch").value="";$("#priceRange").value=500000;$("#priceRangeLabel").textContent=money(500000);$("#stockOnly").checked=false;$("#offersOnly").checked=false;$("#sortSelect").value="featured";renderCategoryNav();renderCatalog()}
function scrollCatalog(){$("#catalog").scrollIntoView({behavior:"smooth",block:"start"})}
function searchNow(){state.filters.query=$("#globalSearch").value.trim();$("#suggestions").classList.add("hidden");renderCatalog();scrollCatalog()}
function showSuggestions(){const q=norm($("#globalSearch").value.trim());if(q.length<2)return $("#suggestions").classList.add("hidden");const list=activeProducts().filter(p=>norm([p.name,p.sku,p.brand,p.category].join(" ")).includes(q)).slice(0,6);$("#suggestions").innerHTML=list.length?list.map(p=>`<button class="suggestion-item" data-suggestion="${p.id}">${imgTag(p)}<span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.sku)} · Stock ${p.stock}</small></span><strong>${money(priceOf(p))}</strong></button>`).join(""):'<div style="padding:14px;color:#6f7b86;font-size:12px">No hay coincidencias.</div>';$("#suggestions").classList.remove("hidden")}
function toggleFavorite(id){const i=state.favorites.indexOf(id);if(i>=0){state.favorites.splice(i,1);toast("Eliminado de favoritos")}else{state.favorites.unshift(id);toast("Guardado en favoritos")}saveAll();renderFeatured();renderCatalog();renderHistory();renderFavorites();updateCounts()}
function updateCounts(){$("#cartCount").textContent=state.cart.reduce((a,x)=>a+x.qty,0);$("#favCount").textContent=state.favorites.length}
function addToCart(id,qty=1){const p=products.find(x=>x.id===id&&x.active!==false);if(!p||p.stock<=0)return toast("Producto sin stock");qty=Math.max(1,Number(qty)||1);const item=state.cart.find(x=>x.id===id),current=item?item.qty:0;if(current+qty>p.stock)return toast(`Stock máximo disponible: ${p.stock}`);if(item)item.qty+=qty;else state.cart.push({id,qty});saveAll();updateCounts();renderCart();toast("Producto agregado al carrito")}
function changeQty(id,d){const item=state.cart.find(x=>x.id===id),p=products.find(x=>x.id===id);if(!item||!p)return;const next=item.qty+d;if(next<1)return removeCart(id);if(next>p.stock)return toast(`Stock máximo disponible: ${p.stock}`);item.qty=next;saveAll();updateCounts();renderCart()}
function removeCart(id){state.cart=state.cart.filter(x=>x.id!==id);saveAll();updateCounts();renderCart()}
function cartTotals(delivery="shipping"){let subtotal=0,regular=0;state.cart.forEach(i=>{const p=products.find(x=>x.id===i.id);if(!p)return;subtotal+=priceOf(p)*i.qty;regular+=Number(p.price)*i.qty});const savings=Math.max(0,regular-subtotal);const shipping=delivery==="pickup"||subtotal>=150000||!state.cart.length?0:4990;return{subtotal,savings,shipping,total:subtotal+shipping}}
function renderCart(){state.cart=state.cart.filter(i=>products.some(p=>p.id===i.id&&p.active!==false));$("#cartItems").innerHTML=state.cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<article class="cart-item">${imgTag(p)}<div><h4>${escapeHtml(p.name)}</h4><b>${money(priceOf(p))}</b><small>${escapeHtml(p.sku)}</small><div class="qty-controls"><button data-cart-dec="${p.id}">−</button><span>${i.qty}</span><button data-cart-inc="${p.id}">+</button><small>/ ${p.stock}</small></div></div><button class="remove-btn" data-cart-remove="${p.id}">Eliminar</button></article>`}).join("");const empty=!state.cart.length;$("#emptyCart").classList.toggle("hidden",!empty);$("#cartSummary").classList.toggle("hidden",empty);const t=cartTotals();$("#cartSubtotal").textContent=money(t.subtotal);$("#cartSavings").textContent=t.savings?`-${money(t.savings)}`:money(0);$("#cartShipping").textContent=t.shipping?money(t.shipping):"Gratis";$("#cartTotal").textContent=money(t.total);saveAll()}
function openProduct(id){const p=products.find(x=>x.id===id&&x.active!==false);if(!p)return;state.viewed=[id,...state.viewed.filter(x=>x!==id)].slice(0,10);saveAll();renderHistory();const related=activeProducts().filter(x=>x.category===p.category&&x.id!==p.id).slice(0,3),offer=isOffer(p);$("#productModalContent").innerHTML=`<div class="product-detail"><div>${imgTag(p,"product-detail-image")}</div><div><span class="eyebrow">${escapeHtml(p.brand)} · ${escapeHtml(p.sku)}</span><h2 id="productModalTitle">${escapeHtml(p.name)}</h2><p>${escapeHtml(p.description)}</p><p><b>Compatibilidad:</b> ${escapeHtml(p.compatibility)}</p><div class="price-line"><b>${money(priceOf(p))}</b>${offer?`<span class="old-price">${money(p.price)}</span><span class="badge sale">-${discountPct(p)}%</span>`:""}</div>${offer&&p.offerUntil?`<p class="offer-until">Precio oferta vigente hasta ${dateCL(p.offerUntil)}</p>`:""}<p><b>Stock disponible:</b> ${p.stock} unidad${p.stock===1?"":"es"}</p><div class="detail-specs">${Object.entries(p.specs||{}).map(([k,v])=>`<div><small>${escapeHtml(k)}</small><b>${escapeHtml(v)}</b></div>`).join("")}</div><div class="detail-buy"><input id="detailQty" type="number" min="1" max="${p.stock}" value="1"><button class="btn accent" id="detailAddBtn" ${p.stock<=0?"disabled":""}>Agregar al carrito</button></div></div></div><div class="related-wrap"><h3>Productos relacionados</h3><div class="product-grid modal-grid">${related.length?related.map(productCard).join(""):'<p class="muted">No hay productos relacionados disponibles.</p>'}</div></div>`;openLayer("product");$("#detailAddBtn")?.addEventListener("click",()=>addToCart(p.id,+$("#detailQty").value||1))}
function renderFavorites(){const list=state.favorites.map(id=>products.find(p=>p.id===id&&p.active!==false)).filter(Boolean);$("#favoritesGrid").innerHTML=list.map(productCard).join("");$("#emptyFavorites").classList.toggle("hidden",!!list.length)}
const LAYERS={product:"#productModal",favorites:"#favoritesModal",cart:"#cartDrawer",checkout:"#checkoutModal",order:"#orderModal",account:"#accountModal",management:"#managementModal",productEditor:"#productEditorModal"};
function openLayer(name){$(LAYERS[name]).classList.remove("hidden");document.body.classList.add("locked")}
function closeLayer(name){$(LAYERS[name])?.classList.add("hidden");if(!Object.values(LAYERS).some(sel=>!$(sel).classList.contains("hidden")))document.body.classList.remove("locked")}
function openCart(){renderCart();openLayer("cart")}
function validRut(v){const s=(v||"").replace(/\./g,"").replace(/-/g,"").trim().toUpperCase();if(!/^\d{7,8}[0-9K]$/.test(s))return false;const body=s.slice(0,-1),dv=s.at(-1);let sum=0,m=2;for(let i=body.length-1;i>=0;i--){sum+=Number(body[i])*m;m=m===7?2:m+1}const r=11-(sum%11),calc=r===11?"0":r===10?"K":String(r);return calc===dv}
function renderCheckout(){const t=cartTotals(document.querySelector('input[name="delivery"]:checked')?.value||"shipping");$("#checkoutItems").innerHTML=state.cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="checkout-mini"><span>${escapeHtml(p.name)} × ${i.qty}</span><b>${money(priceOf(p)*i.qty)}</b></div>`}).join("");$("#checkoutSubtotal").textContent=money(t.subtotal);$("#checkoutSavings").textContent=t.savings?`-${money(t.savings)}`:money(0);$("#checkoutShipping").textContent=t.shipping?money(t.shipping):"Gratis";$("#checkoutTotal").textContent=money(t.total)}
function openCheckout(){if(!state.cart.length)return toast("Tu carrito está vacío");for(const i of state.cart){const p=products.find(x=>x.id===i.id);if(!p||i.qty>p.stock)return toast(`Revisa el stock de ${p?.name||"un producto"}`)}closeLayer("cart");fillCheckoutProfile();renderCheckout();openLayer("checkout")}
function fillCheckoutProfile(){const f=$("#checkoutForm");for(const [k,v] of Object.entries(state.profile||{})){if(f.elements[k]&&v)f.elements[k].value=v}}
function checkoutErrors(fd){const e=[];if((fd.get("name")||"").trim().length<3)e.push("Ingresa un nombre válido.");if(!validRut(fd.get("rut")))e.push("El RUT no es válido.");if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fd.get("email")||""))e.push("El correo no es válido.");if(!/^\+?[\d\s-]{8,16}$/.test((fd.get("phone")||"").trim()))e.push("El teléfono no es válido.");if(fd.get("delivery")==="shipping"){if(!(fd.get("address")||"").trim())e.push("Ingresa la dirección.");if(!(fd.get("commune")||"").trim())e.push("Ingresa la comuna.");if(!fd.get("region"))e.push("Selecciona la región.")}for(const i of state.cart){const p=products.find(x=>x.id===i.id);if(!p||i.qty>p.stock)e.push(`Stock insuficiente para ${p?.name||"un producto"}.`)}return e}
function createOrderId(){const d=new Date(),r=Math.floor(1000+Math.random()*9000);return `NT-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,"0")}${String(d.getDate()).padStart(2,"0")}-${r}`}
function submitOrder(form){const fd=new FormData(form),errs=checkoutErrors(fd),box=$("#checkoutErrors");if(errs.length){box.innerHTML=errs.map(x=>`• ${escapeHtml(x)}`).join("<br>");box.classList.remove("hidden");return}box.classList.add("hidden");const delivery=fd.get("delivery"),t=cartTotals(delivery),customer={name:fd.get("name").trim(),rut:fd.get("rut").trim(),email:fd.get("email").trim(),phone:fd.get("phone").trim(),address:fd.get("address")?.trim()||"",commune:fd.get("commune")?.trim()||"",region:fd.get("region")||""};if(fd.get("saveProfile")){state.profile=customer}const items=state.cart.map(i=>{const p=products.find(x=>x.id===i.id);p.stock-=i.qty;return{id:p.id,sku:p.sku,name:p.name,qty:i.qty,unitPrice:priceOf(p)}});const order={id:createOrderId(),createdAt:new Date().toISOString(),status:"Recibido",customer,delivery,payment:fd.get("payment"),items,totals:t};state.orders.unshift(order);state.cart=[];saveAll();renderAll();closeLayer("checkout");$("#orderMessage").textContent=`Orden ${order.id} por ${money(order.totals.total)}. Estado inicial: ${order.status}.`;openLayer("order");form.reset();$("#shippingFields").classList.remove("hidden")}
function renderAccount(){const f=$("#profileForm");for(const name of ["name","rut","email","phone","address","commune","region"]){f.elements[name].value=state.profile?.[name]||""}$("#accountOrders").innerHTML=state.orders.length?state.orders.map(o=>`<article class="order-card"><div class="order-card-head"><div><h4>${escapeHtml(o.id)}</h4><div class="order-meta"><span>${dateCL(o.createdAt)}</span><span>${o.delivery==="pickup"?"Retiro":"Despacho"}</span><span>${escapeHtml(o.payment)}</span></div></div><span class="status-pill" data-status="${escapeHtml(o.status)}">${escapeHtml(o.status)}</span></div><div class="order-meta"><span>${o.items.reduce((a,i)=>a+i.qty,0)} unidades</span><strong>${money(o.totals.total)}</strong></div></article>`).join(""):'<div class="empty-state"><h3>Aún no tienes pedidos</h3><p>Cuando completes una compra aparecerá en este historial.</p></div>'}
function renderManagement(){if(!$("#managementKpis"))return;const active=activeProducts(),offers=active.filter(isOffer),units=active.reduce((a,p)=>a+p.stock,0),inventory=active.reduce((a,p)=>a+p.stock*priceOf(p),0),revenue=state.orders.reduce((a,o)=>a+(o.totals?.total||0),0);$("#managementKpis").innerHTML=[['Productos publicados',active.length],['Unidades en stock',units],['Ofertas activas',offers.length],['Ventas registradas',money(revenue)]].map(([l,v])=>`<div class="kpi-card"><small>${l}</small><b>${v}</b></div>`).join("");const low=active.filter(p=>p.stock<=6).sort((a,b)=>a.stock-b.stock);$("#lowStockList").innerHTML=low.length?low.map(p=>`<div class="low-stock-row"><span>${escapeHtml(p.name)}</span><b>${p.stock}</b></div>`).join(""):'<p class="muted">No hay productos con stock crítico.</p>';$("#commercialSummary").innerHTML=`<div class="commercial-row"><span>Valor de inventario</span><b>${money(inventory)}</b></div><div class="commercial-row"><span>Pedidos acumulados</span><b>${state.orders.length}</b></div><div class="commercial-row"><span>Ticket promedio</span><b>${money(state.orders.length?revenue/state.orders.length:0)}</b></div><div class="commercial-row"><span>Productos agotados</span><b>${active.filter(p=>p.stock<=0).length}</b></div>`;renderAdminProducts();renderAdminOffers();renderAdminOrders();renderOfferSelect()}
function renderAdminProducts(){const q=norm($("#adminProductSearch")?.value||"");const list=products.filter(p=>!q||norm([p.name,p.sku,p.brand,p.category].join(" ")).includes(q));$("#adminProductsBody").innerHTML=list.map(p=>`<tr><td><div class="admin-product">${imgTag(p)}<span><b>${escapeHtml(p.name)}</b><small class="muted block">${escapeHtml(p.brand)} · ${escapeHtml(p.category)}</small></span></div></td><td>${escapeHtml(p.sku)}</td><td>${money(priceOf(p))}${isOffer(p)?`<small class="muted block">Base ${money(p.price)}</small>`:""}</td><td><b>${p.stock}</b></td><td><span class="status-pill">${p.active===false?"Oculto":p.stock<=0?"Agotado":"Publicado"}</span></td><td><div class="table-actions"><button data-admin-edit="${p.id}">Editar</button><button class="danger-btn" data-admin-delete="${p.id}">Eliminar</button></div></td></tr>`).join("")}
function renderOfferSelect(){$("#offerProductSelect").innerHTML=products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${money(p.price)}</option>`).join("")}
function renderAdminOffers(){const list=products.filter(isOffer);$("#adminOffersList").innerHTML=list.length?list.map(p=>`<div class="admin-offer">${imgTag(p)}<div><b>${escapeHtml(p.name)}</b><small>${money(p.price)} → ${money(p.offerPrice)} · ${discountPct(p)}% menos${p.offerUntil?` · hasta ${dateCL(p.offerUntil)}`:""}</small></div><button class="btn compact" data-remove-offer="${p.id}">Quitar oferta</button></div>`).join(""):'<p class="muted">No hay ofertas activas.</p>'}
function renderAdminOrders(){const statuses=["Recibido","Preparando","Despachado","Entregado","Cancelado"];$("#ordersAdminCount").textContent=`${state.orders.length} pedido${state.orders.length===1?"":"s"}`;$("#adminOrdersBody").innerHTML=state.orders.length?state.orders.map(o=>`<tr><td><b>${escapeHtml(o.id)}</b></td><td>${escapeHtml(o.customer.name)}<small class="muted block">${escapeHtml(o.customer.email)}</small></td><td>${money(o.totals.total)}</td><td>${o.delivery==="pickup"?"Retiro":"Despacho"}</td><td><select data-order-status="${escapeHtml(o.id)}">${statuses.map(s=>`<option ${s===o.status?"selected":""}>${s}</option>`).join("")}</select></td><td>${dateCL(o.createdAt)}</td></tr>`).join(""):'<tr><td colspan="6" class="muted">No hay pedidos registrados.</td></tr>'}
function openProductEditor(id=null){editingProductId=id;pendingImageData=null;const f=$("#productEditorForm");f.reset();$("#productImageStatus").textContent="JPG, PNG o WebP. La imagen se optimiza antes de guardarse.";$("#productEditorErrors").classList.add("hidden");if(id){const p=products.find(x=>x.id===id);$("#productEditorTitle").textContent="Editar producto";for(const k of ["id","name","sku","brand","category","price","stock","compatibility","description"]){if(f.elements[k])f.elements[k].value=p[k]??""}f.elements.imageUrl.value=p.image?.startsWith("data:")?"":p.image||"";f.elements.featured.checked=!!p.featured;f.elements.active.checked=p.active!==false}else{$("#productEditorTitle").textContent="Nuevo producto";f.elements.active.checked=true}openLayer("productEditor")}
function resizeImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const maxW=1000,maxH=750,scale=Math.min(1,maxW/img.width,maxH/img.height),w=Math.round(img.width*scale),h=Math.round(img.height*scale),c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(img,0,0,w,h);resolve(c.toDataURL("image/jpeg",.82))};img.onerror=reject;img.src=reader.result};reader.onerror=reject;reader.readAsDataURL(file)})}
function saveProductFromForm(form){const fd=new FormData(form),errors=[],sku=fd.get("sku").trim().toUpperCase(),name=fd.get("name").trim(),price=Number(fd.get("price")),stock=Number(fd.get("stock"));if(!name)errors.push("El nombre es obligatorio.");if(!sku)errors.push("El SKU es obligatorio.");if(products.some(p=>p.sku.toUpperCase()===sku&&p.id!==editingProductId))errors.push("El SKU ya existe.");if(!Number.isFinite(price)||price<=0)errors.push("El precio debe ser mayor que cero.");if(!Number.isInteger(stock)||stock<0)errors.push("El stock debe ser cero o un entero positivo.");for(const k of ["brand","category","compatibility","description"])if(!fd.get(k)?.trim())errors.push(`Completa el campo ${k}.`);const box=$("#productEditorErrors");if(errors.length){box.innerHTML=errors.map(e=>`• ${escapeHtml(e)}`).join("<br>");box.classList.remove("hidden");return}const existing=products.find(p=>p.id===editingProductId),image=pendingImageData||fd.get("imageUrl").trim()||existing?.image||fallbackImage(),obj={id:existing?.id||Date.now(),sku,name,brand:fd.get("brand").trim(),category:fd.get("category").trim(),price,offerPrice:existing?.offerPrice||null,offerUntil:existing?.offerUntil||null,stock,compatibility:fd.get("compatibility").trim(),description:fd.get("description").trim(),specs:existing?.specs||{Estado:"Nuevo",Venta:"Unidad"},image,featured:fd.get("featured")==="on",active:fd.get("active")==="on"};if(existing)Object.assign(existing,obj);else products.unshift(obj);saveAll();closeLayer("productEditor");renderAll();toast(existing?"Producto actualizado":"Producto creado")}
function deleteProduct(id){const p=products.find(x=>x.id===id);if(!p)return;if(!confirm(`¿Eliminar ${p.name}? Esta acción también lo quitará de carritos y favoritos.`))return;products=products.filter(x=>x.id!==id);state.cart=state.cart.filter(x=>x.id!==id);state.favorites=state.favorites.filter(x=>x!==id);state.viewed=state.viewed.filter(x=>x!==id);saveAll();renderAll();toast("Producto eliminado")}
function saveOffer(form){const fd=new FormData(form),id=Number(fd.get("productId")),p=products.find(x=>x.id===id),offer=Number(fd.get("offerPrice"));if(!p)return;if(!offer||offer<=0||offer>=p.price)return toast("El precio oferta debe ser menor al precio base");p.offerPrice=offer;p.offerUntil=fd.get("offerUntil")||null;saveAll();form.reset();renderAll();toast("Oferta publicada")}
function removeOffer(id){const p=products.find(x=>x.id===id);if(!p)return;p.offerPrice=null;p.offerUntil=null;saveAll();renderAll();toast("Oferta retirada")}
function downloadBlob(name,type,text){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(u)}
function exportCatalog(){downloadBlob(`axoryn_catalogo_${new Date().toISOString().slice(0,10)}.json`,"application/json;charset=utf-8",JSON.stringify(products,null,2))}
function importCatalog(file){const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);if(!Array.isArray(data)||!data.length||!data.every(p=>p.name&&p.sku&&p.price!==undefined&&p.stock!==undefined))throw new Error();const skus=new Set();for(const p of data){if(skus.has(p.sku))throw new Error();skus.add(p.sku);p.id=Number(p.id)||Date.now()+Math.random();p.active=p.active!==false}products=data;saveAll();renderAll();toast("Catálogo importado correctamente")}catch{toast("El archivo no contiene un catálogo válido")}};r.readAsText(file)}
function exportOrders(){const esc=v=>`"${String(v??"").replace(/"/g,'""')}"`,rows=[["Orden","Fecha","Estado","Cliente","RUT","Correo","Entrega","Pago","Total"]];state.orders.forEach(o=>rows.push([o.id,dateCL(o.createdAt),o.status,o.customer.name,o.customer.rut,o.customer.email,o.delivery==="pickup"?"Retiro":"Despacho",o.payment,o.totals.total]));downloadBlob(`axoryn_pedidos_${new Date().toISOString().slice(0,10)}.csv`,"text/csv;charset=utf-8","\ufeff"+rows.map(r=>r.map(esc).join(";")).join("\n"))}
function openManagement(){renderManagement();openLayer("management")}
function switchManagementTab(tab){$$('[data-mtab]').forEach(b=>b.classList.toggle("active",b.dataset.mtab===tab));$$('[data-mview]').forEach(v=>v.classList.toggle("hidden",v.dataset.mview!==tab))}
function parseMoneyFromText(q){const m=q.match(/(?:menos de|hasta|por debajo de|bajo)\s*\$?\s*([\d\.]+)/);return m?Number(m[1].replace(/\./g,"")):null}
function productScore(p,q){const nq=norm(q),tokens=norm(`${p.name} ${p.brand} ${p.sku}`).split(/[^a-z0-9]+/).filter(t=>t.length>=3);let score=0;if(nq.includes(norm(p.sku)))score+=20;if(nq.includes(norm(p.name)))score+=15;if(nq.includes(norm(p.brand)))score+=5;for(const t of tokens)if(nq.includes(t))score+=1;return score}
function matchProduct(q){return activeProducts().map(p=>[p,productScore(p,q)]).sort((a,b)=>b[1]-a[1]).find(x=>x[1]>=2)?.[0]||null}
function addChat(text,who="bot",product=null){const d=document.createElement("div");d.className=`msg ${who}`;d.innerHTML=`<div>${text}</div>${product?`<div class="chat-product">${imgTag(product)}<b>${escapeHtml(product.name)}</b><small>${money(priceOf(product))} · Stock ${product.stock}</small><button data-chat-product="${product.id}">Ver producto</button></div>`:""}`;$("#chatMessages").appendChild(d);$("#chatMessages").scrollTop=$("#chatMessages").scrollHeight}
function chatProductAnswer(p,q){const nq=norm(q),offer=isOffer(p);if(/oferta|descuento|rebaja|promocion/.test(nq))return addChat(offer?`${escapeHtml(p.name)} está en oferta a <b>${money(priceOf(p))}</b>, antes ${money(p.price)}. El descuento es ${discountPct(p)}%${p.offerUntil?` y rige hasta ${dateCL(p.offerUntil)}`:""}.`:`${escapeHtml(p.name)} no tiene una oferta activa. Su precio actual es <b>${money(p.price)}</b>.`,"bot",p);if(/stock|disponib|queda|hay unidades|tienen/.test(nq))return addChat(p.stock>0?`Hay <b>${p.stock} unidades</b> disponibles de ${escapeHtml(p.name)}.`:`${escapeHtml(p.name)} está sin stock en este momento.`,"bot",p);if(/compat|sirve|funciona|vehiculo|auto|modelo|vin|oem/.test(nq))return addChat(`Compatibilidad informada para ${escapeHtml(p.name)}: ${escapeHtml(p.compatibility)}. Para una pieza crítica conviene validar VIN, código OEM, medida o socket antes de comprar.`,"bot",p);if(/precio|cuanto|cuesta|vale|valor/.test(nq))return addChat(`${escapeHtml(p.name)} cuesta <b>${money(priceOf(p))}</b>${offer?` y está en oferta; su precio base es ${money(p.price)}`:""}. Stock disponible: ${p.stock}.`,"bot",p);return addChat(`${escapeHtml(p.name)} · ${escapeHtml(p.sku)} · ${money(priceOf(p))} · Stock ${p.stock}. ${escapeHtml(p.description)}`,"bot",p)}
function botReply(text){const q=norm(text),p=matchProduct(text);if(p&&/(precio|cuanto|cuesta|vale|valor|oferta|descuento|stock|disponib|compat|sirve|funciona|vehiculo|auto|modelo|vin|oem|bateria|filtro|pastilla|led|aceite|scanner|obd|dashcam|cargador|tpms|radio|bujia|herramienta)/.test(q))return chatProductAnswer(p,text);if(/hola|buenas|ayuda|que puedes hacer/.test(q))return addChat("Puedo consultar todo el catálogo en tiempo real: precios, ofertas, stock, SKU, marcas, categorías, compatibilidad, productos más baratos o caros, despacho, retiro, garantías y estado general de compra.");if(/que productos.*oferta|ofertas|promociones|descuentos/.test(q)){const list=activeProducts().filter(isOffer).sort((a,b)=>discountPct(b)-discountPct(a));if(!list.length)return addChat("No hay ofertas activas en este momento.");return addChat(`Hay <b>${list.length} ofertas activas</b>. La mayor rebaja es ${escapeHtml(list[0].name)} con ${discountPct(list[0])}% de descuento, a ${money(priceOf(list[0]))}.`,"bot",list[0])}if(/mas barato|menor precio|economico/.test(q)){const x=activeProducts().filter(p=>p.stock>0).sort((a,b)=>priceOf(a)-priceOf(b))[0];return addChat(`El producto disponible de menor precio es ${escapeHtml(x.name)} por <b>${money(priceOf(x))}</b>.`,"bot",x)}if(/mas caro|mayor precio/.test(q)){const x=activeProducts().filter(p=>p.stock>0).sort((a,b)=>priceOf(b)-priceOf(a))[0];return addChat(`El producto de mayor precio es ${escapeHtml(x.name)} por <b>${money(priceOf(x))}</b>.`,"bot",x)}if(/categorias|categoria/.test(q)){const cats=[...new Set(activeProducts().map(p=>p.category))];return addChat(`Tenemos ${cats.length} categorías: ${cats.map(escapeHtml).join(", ")}.`)}if(/marcas|marca/.test(q)){const brands=[...new Set(activeProducts().map(p=>p.brand))];const named=brands.find(b=>q.includes(norm(b)));if(named){const list=activeProducts().filter(p=>p.brand===named);return addChat(`De ${escapeHtml(named)} tenemos ${list.map(p=>`${escapeHtml(p.name)} (${money(priceOf(p))})`).join("; ")}.`,"bot",list[0])}return addChat(`Trabajamos con ${brands.length} marcas en el catálogo actual: ${brands.map(escapeHtml).join(", ")}.`)}const limit=parseMoneyFromText(q);if(limit){const list=activeProducts().filter(p=>p.stock>0&&priceOf(p)<=limit).sort((a,b)=>priceOf(a)-priceOf(b));if(!list.length)return addChat(`No hay productos disponibles bajo ${money(limit)}.`);return addChat(`Encontré ${list.length} producto${list.length===1?"":"s"} hasta ${money(limit)}. El primero es ${escapeHtml(list[0].name)} por ${money(priceOf(list[0]))}.`,"bot",list[0])}if(/despach|envio|entrega|retiro/.test(q))return addChat("Puedes elegir despacho o retiro al finalizar la compra. El despacho cuesta $4.990 y queda sin costo desde $150.000; el retiro no tiene costo.");if(/garantia|garantias/.test(q))return addChat("La garantía se informa en la ficha de cada producto cuando está definida. Para repuestos, la compatibilidad y una instalación correcta son condiciones relevantes para la evaluación de garantía.");if(/pago|webpay|debito|credito|transferencia/.test(q))return addChat("En el checkout puedes seleccionar Webpay Plus, tarjeta de débito, tarjeta de crédito o transferencia. El pedido queda registrado con el medio elegido.");if(/carrito|comprar|compra/.test(q))return addChat("El carrito valida stock, limita cantidades al inventario disponible, mantiene los productos al recargar la página y vuelve a validar existencias antes de crear el pedido.");if(/pedido|orden|estado/.test(q)){const last=state.orders[0];return last?addChat(`La orden más reciente registrada en este navegador es ${escapeHtml(last.id)} y su estado es <b>${escapeHtml(last.status)}</b>. Puedes revisar el historial completo en Mi cuenta.`):addChat("Todavía no hay pedidos registrados en este navegador.")}if(/stock|inventario|disponibles/.test(q)){const total=activeProducts().reduce((a,p)=>a+p.stock,0),out=activeProducts().filter(p=>p.stock<=0).length;return addChat(`El catálogo tiene ${total} unidades en inventario distribuidas en ${activeProducts().length} productos. ${out?`${out} productos están agotados.`:"No hay productos agotados."}`)}const keywords=q.split(/\s+/).filter(x=>x.length>3),matches=activeProducts().filter(p=>keywords.some(k=>norm([p.name,p.brand,p.category,p.description,p.compatibility].join(" ")).includes(k)));if(matches.length)return addChat(`Encontré ${matches.length} producto${matches.length===1?"":"s"} relacionado${matches.length===1?"":"s"}. Te muestro la mejor coincidencia.`,"bot",matches[0]);addChat("No encontré una coincidencia exacta. Puedes preguntarme, por ejemplo: “¿cuánto cuesta la batería?”, “¿el scanner está en oferta?”, “¿qué productos tienen stock?”, “¿qué hay bajo $50.000?” o “¿cómo funciona el despacho?”.")}
function sendChat(text){text=text.trim();if(!text)return;addChat(escapeHtml(text),"user");$("#chatInput").value="";setTimeout(()=>botReply(text),160)}
function ensureChat(){if(!$("#chatMessages").children.length)addChat("Hola. Soy TorqueBot. Conozco los productos y el stock actual de Axoryn Auto. Pregúntame por precios, ofertas, SKU, compatibilidad, categorías o disponibilidad.")}
function showFlashOffer(){if(localStorage.getItem("axoryn.dismissFlashOffer"))return;const best=activeProducts().filter(isOffer).sort((a,b)=>discountPct(b)-discountPct(a))[0];if(!best)return;promoProductId=best.id;$("#flashOfferTitle").textContent=`${best.name} · -${discountPct(best)}%`;$("#flashOfferText").textContent=`Sólo ${best.stock} unidades demo disponibles a ${money(priceOf(best))}. Revisa la compatibilidad antes de agregarlo.`;$("#flashOfferPopup").classList.remove("hidden")}
function closeFlashOffer(remember=false){$("#flashOfferPopup").classList.add("hidden");if(remember)localStorage.setItem("axoryn.dismissFlashOffer","1")}
function scrollTech(){$("#technologies").scrollIntoView({behavior:"smooth",block:"start"});$("#mobileMenu").classList.add("hidden")}

// Delegated actions
document.addEventListener("click",e=>{const a=e.target.closest("[data-action]");if(a){const id=Number(a.dataset.id);if(a.dataset.action==="fav")toggleFavorite(id);if(a.dataset.action==="add")addToCart(id);if(a.dataset.action==="view")openProduct(id);return}const c=e.target.closest("[data-close]");if(c)return closeLayer(c.dataset.close);const nav=e.target.closest("[data-nav]");if(nav){nav.dataset.nav==="home"?window.scrollTo({top:0,behavior:"smooth"}):scrollCatalog();$("#mobileMenu").classList.add("hidden");return}const sug=e.target.closest("[data-suggestion]");if(sug){openProduct(Number(sug.dataset.suggestion));$("#suggestions").classList.add("hidden");return}const cat=e.target.closest("[data-cat-card]");if(cat){state.filters.category=cat.dataset.catCard;renderCategoryNav();renderCatalog();scrollCatalog();return}const cp=e.target.closest("[data-chat-product]");if(cp)return openProduct(Number(cp.dataset.chatProduct));const quick=e.target.closest("[data-chat]");if(quick)return sendChat(quick.dataset.chat);const inc=e.target.closest("[data-cart-inc]");if(inc)return changeQty(Number(inc.dataset.cartInc),1);const dec=e.target.closest("[data-cart-dec]");if(dec)return changeQty(Number(dec.dataset.cartDec),-1);const rem=e.target.closest("[data-cart-remove]");if(rem)return removeCart(Number(rem.dataset.cartRemove));const ed=e.target.closest("[data-admin-edit]");if(ed)return openProductEditor(Number(ed.dataset.adminEdit));const del=e.target.closest("[data-admin-delete]");if(del)return deleteProduct(Number(del.dataset.adminDelete));const ro=e.target.closest("[data-remove-offer]");if(ro)return removeOffer(Number(ro.dataset.removeOffer))});
