const openProductBase=openProduct;openProduct=function(id){openProductBase(id);const p=products.find(x=>x.id===id);if(!p)return;const score=(4.5+(id%4)/10).toFixed(1),reviews=["Instalación y entrega demo correctamente informadas.","Buena ficha técnica; se recomienda validar la compatibilidad.","Producto de referencia con especificaciones claras."];$("#productModalContent").insertAdjacentHTML("beforeend",`<section class="review-summary" aria-label="Reseñas demostrativas"><div><b>${score} / 5</b><span aria-label="${score} de 5 estrellas">★★★★★</span><small>Reseñas de demostración</small></div><div><h3>Opiniones de compradores</h3>${reviews.map((r,i)=>`<article><b>${["Camila R.","Tomás M.","Javiera P."][i]}</b><span>★★★★★</span><p>${r}</p></article>`).join("")}</div></section>`)};
